-- Arbeitsrecht Berufsbildung > Wirtschaftliche Zusammenhänge > Marktmechanismen > Preisbildung
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wird der Preis für IT-Dienstleistungen durch das Zusammenspiel von Angebot und Nachfrage bestimmt?', 2, '[{"text": "Ja", "correct": true, "because": "Preisbildung entsteht durch Angebot und Nachfrage"}, {"text": "Nein", "correct": false, "because": "Das ist das Grundprinzip der Marktpreisbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Steigt der Preis für Softwarelizenzen, wenn die Nachfrage größer ist als das Angebot?', 2, '[{"text": "Ja", "correct": true, "because": "Knappheit erhöht den Preis"}, {"text": "Nein", "correct": false, "because": "Nachfrageüberschuss treibt Preise hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Preisbildung für IT-Hardware durch staatliche Eingriffe beeinflusst werden?', 2, '[{"text": "Ja", "correct": true, "because": "Subventionen oder Steuern wirken auf den Preis"}, {"text": "Nein", "correct": false, "because": "Staatliche Maßnahmen beeinflussen Preise"}]'),
('00000000-0000-0000-0000-000000000000', 'Sinkt der Preis für Programmierdienstleistungen, wenn das Angebot die Nachfrage übersteigt?', 2, '[{"text": "Ja", "correct": true, "because": "Überschuss senkt den Preis"}, {"text": "Nein", "correct": false, "because": "Angebotsüberschuss drückt Preise"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Preisbildung für IT-Produkte unabhängig von den Produktionskosten?', 2, '[{"text": "Nein", "correct": true, "because": "Produktionskosten beeinflussen das Angebot und damit den Preis"}, {"text": "Ja", "correct": false, "because": "Kosten sind ein indirekter Faktor"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was bestimmt die Preisbildung für IT-Dienstleistungen eines IT-Betriebs?', 2, '[{"text": "Angebot und Nachfrage", "correct": true, "because": "Grundprinzip der Marktpreisbildung"}, {"text": "Nur die Nachfrage", "correct": false, "because": "Angebot ist ebenfalls entscheidend"}, {"text": "Festlegung durch den Betrieb", "correct": false, "because": "Marktkräfte bestimmen den Preis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Zustand führt zu einem höheren Preis für Software eines IT-Betriebs?', 3, '[{"text": "Nachfrage übersteigt Angebot", "correct": true, "because": "Knappheit erhöht den Preis"}, {"text": "Angebot übersteigt Nachfrage", "correct": false, "because": "Das senkt den Preis"}, {"text": "Gleiches Angebot und Nachfrage", "correct": false, "because": "Das stabilisiert den Preis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor kann die Preisbildung für IT-Hardware verzerren?', 3, '[{"text": "Staatliche Subventionen", "correct": true, "because": "Subventionen senken Produktionskosten"}, {"text": "Farbe der Hardware", "correct": false, "because": "Irrelevant für Preisbildung"}, {"text": "Größe des Betriebs", "correct": false, "because": "Indirekter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert bei einem Überangebot an Programmierdienstleistungen?', 2, '[{"text": "Der Preis sinkt", "correct": true, "because": "Überschuss drückt den Preis"}, {"text": "Der Preis steigt", "correct": false, "because": "Überschuss senkt den Preis"}, {"text": "Der Preis bleibt gleich", "correct": false, "because": "Markt reagiert auf Überschuss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Preisbildung für einen IT-Betrieb?', 3, '[{"text": "Sie bestimmt den Marktpreis für Dienstleistungen", "correct": true, "because": "Preisbildung gleicht Angebot und Nachfrage aus"}, {"text": "Sie zeigt nur die Produktionskosten", "correct": false, "because": "Kosten sind nur ein Faktor"}, {"text": "Sie ist unwichtig für den Gewinn", "correct": false, "because": "Preis beeinflusst Gewinn"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Preisbildung für IT-Dienstleistungen eines IT-Betriebs?', 4, '[{"text": "Angebot von Dienstleistungen", "correct": true, "because": "Angebot beeinflusst den Preis"}, {"text": "Nachfrage der Kunden", "correct": true, "because": "Nachfrage treibt den Preis"}, {"text": "Farbe der Büromöbel", "correct": false, "because": "Irrelevant"}, {"text": "Produktionskosten", "correct": true, "because": "Kosten wirken auf das Angebot"}]'),
('00000000-0000-0000-0000-000000000000', 'Was führt zu einem Anstieg des Preises für Software eines IT-Betriebs?', 3, '[{"text": "Hohe Nachfrage", "correct": true, "because": "Nachfrageüberschuss erhöht Preise"}, {"text": "Geringes Angebot", "correct": true, "because": "Knappheit treibt Preise"}, {"text": "Hohe Produktionskosten", "correct": true, "because": "Kosten können Angebot verringern"}, {"text": "Sinkende Qualität", "correct": false, "because": "Senkt eher die Nachfrage"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen treffen auf die Preisbildung eines IT-Betriebs zu?', 4, '[{"text": "Preise steigen bei Nachfrageüberschuss", "correct": true, "because": "Grundprinzip der Marktpreisbildung"}, {"text": "Preise sinken bei Angebotsüberschuss", "correct": true, "because": "Überschuss drückt Preise"}, {"text": "Preise sind immer fix", "correct": false, "because": "Preise schwanken"}, {"text": "Angebot und Nachfrage bestimmen den Preis", "correct": true, "because": "Marktmechanismus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche externen Einflüsse können die Preisbildung für IT-Hardware verändern?', 3, '[{"text": "Staatliche Regulierung", "correct": true, "because": "Steuern oder Subventionen wirken"}, {"text": "Wettbewerb", "correct": true, "because": "Konkurrenz beeinflusst Preise"}, {"text": "Wetterbedingungen", "correct": false, "because": "Weniger relevant"}, {"text": "Markteintritt neuer Anbieter", "correct": true, "because": "Mehr Angebot senkt Preise"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert bei der Preisbildung, wenn Angebot und Nachfrage im Gleichgewicht sind?', 3, '[{"text": "Der Preis stabilisiert sich", "correct": true, "because": "Gleichgewichtspreis entsteht"}, {"text": "Angebot und Nachfrage sind gleich", "correct": true, "because": "Definition des Gleichgewichts"}, {"text": "Preise steigen weiter", "correct": false, "because": "Preise stabilisieren sich"}, {"text": "Nachfrage sinkt automatisch", "correct": false, "because": "Keine automatische Änderung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Preisbildung wird durch Angebot und Nachfrage bestimmt. b) Produktionskosten haben keinen Einfluss auf den Preis.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Angebot/Nachfrage ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Nachfrageüberschuss erhöht den Preis für IT-Dienstleistungen. b) Ein Angebotsüberschuss erhöht den Preis.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nachfrageüberschuss ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Staatliche Subventionen können den Preis für IT-Hardware senken. b) Wettbewerb hat keinen Einfluss auf die Preisbildung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Subventionen ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Bei Gleichgewicht stabilisiert sich der Preis für Software. b) Preisbildung ist unabhängig von Angebot und Nachfrage.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gleichgewicht ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Anstieg der Nachfrage erhöht den Preis für IT-Dienstleistungen. b) Preisbildung zeigt nur die Kosten eines IT-Betriebs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nachfrageanstieg ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

